<?php $modalInstructors = $pdo->query("SELECT id, COALESCE(full_name, username) AS display_name FROM users WHERE role='instructor' AND status='active' ORDER BY display_name")->fetchAll(PDO::FETCH_ASSOC); ?>
<div class="modal fade" id="addCourseModal" tabindex="-1" aria-labelledby="addCourseModalLabel" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content border-0 shadow"><form method="post" action="/Admin-dashboard/Courses/add_course/add_course.php"><div class="modal-header"><div><span class="page-kicker">LEARNING CATALOG</span><h2 class="modal-title h5" id="addCourseModalLabel">Add course</h2></div><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($adminCsrfToken,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="add_course" value="1"><label class="form-label" for="newCourseTitle">Course title</label><input class="form-control mb-3" id="newCourseTitle" name="course_name" maxlength="100" required><label class="form-label" for="newCourseCategory">Category</label><input class="form-control mb-3" id="newCourseCategory" name="category" maxlength="50"><label class="form-label" for="newCourseInstructor">Instructor</label><select class="form-select mb-3" id="newCourseInstructor" name="instructor_id" required><option value="">Choose an active instructor</option><?php foreach($modalInstructors as $instructor):?><option value="<?=(int)$instructor['id']?>"><?=htmlspecialchars($instructor['display_name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select><label class="form-label" for="newCourseDescription">Description</label><textarea class="form-control" id="newCourseDescription" name="description" rows="3"></textarea></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" type="submit" <?=$modalInstructors?'':'disabled'?>>Create course</button></div></form></div></div></div>
